-- 0022: Scrapping, the 7th skill, and the Thrift Store's dumpsters (docs/design.md §14). GENERATED by
-- scripts/scrapping-sql.ts.
--
-- Scrapping uses the street-crime machinery (spots, attempts, empty spots that refill), with a skill per crime:
--  - players.scrapping_xp; crimes.skill ('street' for every crime there is, 'scrapping' for the new one);
--  - the crime tin_salvage: 4 ticks a try, 50% to find something (+0.5% a level), 4 XP, 1 Tin Salvage; finding
--    nothing costs nothing (no damage, no stun: "You find nothing useful."); a dumpster you found something in is empty
--    for 15 s;
--  - spots: the 5 dumpsters behind the Thrift Store (009); the item tin_salvage ($5);
--  - start_attempt checks the crime's own skill level; finish_attempt gives the XP (and level-ups) to that skill, names
--    the item it gave you, and has no big scores for scrapping; save, respond and get_highscores know Scrapping.
-- Changed lines are swapped in the live definitions (it stops if one isn't found). Additive: no player data is changed.

alter table public.players add column if not exists scrapping_xp bigint not null default 0;
alter table public.crimes add column if not exists skill text not null default 'street';

insert into public.items (id, name, slot, damage, accuracy, defence, speed, needs_skill, needs_level, heal, value)
values ('tin_salvage', 'Tin Salvage', null, 0, 0, 0, null, null, 1, 0, 5)
on conflict (id) do update set name = excluded.name, value = excluded.value;

insert into public.crimes (id, name, level, ticks, base_chance, xp, cash_min, cash_max, items, fail_damage, fail_stun, catcher, refill, skill)
values ('tin_salvage', 'Tin Salvaging', 1, 4, 0.5, 4, 0, 0, array['tin_salvage']::text[],
  0, 0, null, 15, 'scrapping')
on conflict (id) do update set name = excluded.name, level = excluded.level, ticks = excluded.ticks, base_chance = excluded.base_chance,
  xp = excluded.xp, items = excluded.items, fail_damage = excluded.fail_damage, fail_stun = excluded.fail_stun, refill = excluded.refill,
  skill = excluded.skill;

insert into public.spots (id, crime_id, x, y) values
  ('dumpster_0', 'tin_salvage', 48, 46),
  ('dumpster_1', 'tin_salvage', 46, 48),
  ('dumpster_2', 'tin_salvage', 50, 48),
  ('dumpster_3', 'tin_salvage', 46, 50),
  ('dumpster_4', 'tin_salvage', 50, 50)
on conflict (id) do update set crime_id = excluded.crime_id, x = excluded.x, y = excluded.y;

do $do$
declare
  r record;
  def text;
begin
  for r in select * from (values
    ('public.start_attempt(text, integer, integer)', E'if game.level_from_xp(p.street_xp) < c.level then', E'if game.level_from_xp(case c.skill when \'scrapping\' then p.scrapping_xp else p.street_xp end) < c.level then'),
    ('public.finish_attempt()', E'lvl_before := game.level_from_xp(p.street_xp);', E'lvl_before := game.level_from_xp(case c.skill when \'scrapping\' then p.scrapping_xp else p.street_xp end);'),
    ('public.finish_attempt()', E'big := random() < 0.05;', E'big := c.skill = \'street\' and random() < 0.05;'),
    ('public.finish_attempt()', E'\'%sYou got away with it. +%s %s, +%s XP\'', E'\'%s\' || case c.skill when \'scrapping\' then \'You find something useful.\' else \'You got away with it.\' end || \' +%s %s, +%s XP\''),
    ('public.finish_attempt()', E'case v_item when \'sandwich\' then \'Sandwich\' else \'Candy Bar\' end', E'coalesce((select i.name from public.items i where i.id = v_item), v_item)'),
    ('public.finish_attempt()', E'p.street_xp := p.street_xp + v_xp;', E'if c.skill = \'scrapping\' then p.scrapping_xp := p.scrapping_xp + v_xp; else p.street_xp := p.street_xp + v_xp; end if;'),
    ('public.finish_attempt()', E'jsonb_build_object(\'street\', v_xp)', E'jsonb_build_object(c.skill, v_xp)'),
    ('public.finish_attempt()', E'lvl_after := game.level_from_xp(p.street_xp);', E'lvl_after := game.level_from_xp(case c.skill when \'scrapping\' then p.scrapping_xp else p.street_xp end);'),
    ('public.finish_attempt()', E'jsonb_build_object(\'skill\', \'street\', \'level\', v_n)', E'jsonb_build_object(\'skill\', c.skill, \'level\', v_n)'),
    ('public.finish_attempt()', E'format(\'Street Crimes reached level %s!\', v_n)', E'format(\'%s reached level %s!\', case c.skill when \'scrapping\' then \'Scrapping\' else \'Street Crimes\' end, v_n)'),
    ('public.finish_attempt()', E'    if c.catcher is not null then\n      p.caught_crime := c.id;', E'    if c.fail_damage = 0 and c.catcher is null then\n      logs := logs || to_jsonb(\'You find nothing useful.\'::text);\n    elsif c.catcher is not null then\n      p.caught_crime := c.id;'),
    ('game.save(public.players)', E'cooking_xp = p.cooking_xp,', E'cooking_xp = p.cooking_xp, scrapping_xp = p.scrapping_xp,'),
    ('game.respond(uuid, boolean, text, jsonb, jsonb)', E'\'cooking\', jsonb_build_object(\'xp\', p.cooking_xp))', E'\'cooking\', jsonb_build_object(\'xp\', p.cooking_xp), \'scrapping\', jsonb_build_object(\'xp\', p.scrapping_xp))'),
    ('public.get_highscores(text, integer)', E'when \'cooking\' then \'cooking_xp\' end;', E'when \'cooking\' then \'cooking_xp\' when \'scrapping\' then \'scrapping_xp\' end;')
  ) as t(fn, old_text, new_text) loop
    def := pg_get_functiondef(r.fn::regprocedure);
    if position(r.old_text in def) = 0 then raise exception '%: anchor not found: %', r.fn, r.old_text; end if;
    execute replace(def, r.old_text, r.new_text);
  end loop;
end $do$;

-- Check: this should say "ok".
select case when (select count(*) from public.spots where crime_id = 'tin_salvage') = 5
  and position('scrapping_xp' in pg_get_functiondef('public.finish_attempt()'::regprocedure)) > 0
  and position('scrapping_xp' in pg_get_functiondef('game.respond(uuid, boolean, text, jsonb, jsonb)'::regprocedure)) > 0
  then 'ok' else 'NOT APPLIED' end as scrapping;
